attribute vec2 a_position;
varying vec2 v_texCoord;
void main() {
    v_texCoord = a_position * 0.5 + 0.5;
    gl_Position = vec4(a_position, 0.0, 1.0);
}

sections.fragmentShader:
precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_pattern;
uniform float u_cacheLineSize;
uniform vec2 u_resolution;

// Simple hash for visualization
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main() {
    // Correct for aspect ratio - make grid square
    float aspect = u_resolution.x / u_resolution.y;
    vec2 uv = v_texCoord;
    uv.x *= aspect;

    // Center the grid
    float gridSize = 16.0;
    float totalWidth = gridSize * aspect;
    float offset = (totalWidth - gridSize) * 0.5;
    uv.x -= offset / gridSize;

    // Simulate a texture grid (16x16 'texels')
    vec2 texelCoord = floor(uv * gridSize);

    // Out of bounds check
    if (texelCoord.x < 0.0 || texelCoord.x >= gridSize || texelCoord.y < 0.0 || texelCoord.y >= gridSize) {
        gl_FragColor = vec4(vec3(0.05, 0.06, 0.08), 1.0);
        return;
    }

    // Cache line: 4 texels wide (simulated)
    vec2 cacheLine = floor(texelCoord / u_cacheLineSize);

    // Current 'fetch' position animated over time
    float t = u_time * 0.5;
    vec2 fetchPos;

    if (u_pattern < 0.5) {
        // Coherent: scan left-to-right, top-to-bottom
        float scanLine = floor(mod(t * 4.0, gridSize));
        float scanCol = mod(t * 64.0, gridSize);
        fetchPos = vec2(scanCol, scanLine);
    } else {
        // Random: jump around unpredictably
        float frame = floor(t * 8.0);
        fetchPos = vec2(
            hash(vec2(frame, 0.0)) * gridSize,
            hash(vec2(0.0, frame)) * gridSize
        );
    }

    vec2 fetchCacheLine = floor(fetchPos / u_cacheLineSize);

    // Visualize cache line hit
    float isActiveCacheLine = step(0.5, 1.0 - length(cacheLine - fetchCacheLine));
    float isActiveTexel = step(length(texelCoord - floor(fetchPos)), 0.5);

    // Color: texel grid with cache line highlighting
    vec3 gridColor = vec3(0.1, 0.12, 0.15);
    vec3 texelColor = mix(gridColor, vec3(0.15, 0.18, 0.22), 
        step(0.5, mod(texelCoord.x + texelCoord.y, 2.0)));

    // Cache line border
    vec2 withinCache = mod(texelCoord, u_cacheLineSize);
    float isCacheBorder = step(withinCache.x, 0.5) + step(withinCache.y, 0.5);
    texelColor = mix(texelColor, vec3(0.2, 0.25, 0.3), min(isCacheBorder, 1.0) * 0.5);

    // Highlight active cache line (what we'd fetch)
    vec3 cacheHitColor = u_pattern < 0.5 ? vec3(0.18, 0.83, 0.75) : vec3(0.91, 0.73, 0.14);
    texelColor = mix(texelColor, cacheHitColor * 0.4, isActiveCacheLine * 0.8);

    // Highlight the actual sampled texel
    texelColor = mix(texelColor, vec3(1.0), isActiveTexel);

    // Grid lines
    vec2 grid = abs(fract(uv * gridSize) - 0.5);
    float gridLine = step(0.42, max(grid.x, grid.y));
    texelColor = mix(texelColor, vec3(0.3), gridLine * 0.3);

    gl_FragColor = vec4(texelColor, 1.0);
}

